  "Pino, assistente di Radici Calabria": "Pino, Radici Calabria assistant",
  "In cosa posso esserti utile?": "How can I help you?",
  "Apri Pino, assistente di Radici Calabria": "Open Pino, the Radici Calabria assistant",
  "Pino assistente virtuale di Radici Calabria": "Pino, Radici Calabria's virtual assistant",
  "Stato richiesto: aperte, turno o tutte.": "Requested status: open, on duty or all.",
  "Cerca farmacie aperte, di turno o tutte.": "Search for open, on-duty or all pharmacies.",
  "Ciao! Sono l'Assistente di LocalHub": "Hi! I'm the LocalHub Assistant",
  "Cerca offerte, promozioni e sconti attivi.": "Search active deals, promotions and discounts.",
  "Cerca eventi, manifestazioni e appuntamenti.": "Search events, shows and appointments.",
  "Cerca prodotti acquistabili nel catalogo locale.": "Search products available in the local catalogue.",
  "Restituisce il meteo aggiornato di Castrovillari.": "Returns the current weather for Castrovillari.",
  "Cerca negozi, attività, professionisti e servizi locali.": "Search shops, businesses, professionals and local services.",
  "Elenca le categorie del catalogo con il numero di negozi.": "Lists catalogue categories with the number of shops.",
  "Cerca articoli e contenuti editoriali pubblicati su Radici Calabria.": "Search articles and editorial content published on Radici Calabria.",
  "Chiedi qualcosa… es. farmacia aperta adesso, pizzeria in centro": "Ask something… e.g. pharmacy open now, pizzeria in the centre",
  "Cerca le ultime notizie pubblicate su Radici Calabria, con fonte e link.": "Search the latest news published on Radici Calabria, with source and link.",
  "Cerca prodotti nelle categorie regalo; strumento interno al fan-out.": "Search products in gift categories; internal fan-out tool.",
  "Posso aiutarti a trovare negozi, servizi e attività locali. Dimmi cosa cerchi!": "I can help you find shops, services and local businesses. Tell me what you're looking for!",
  "Cerca trasversalmente negozi, prodotti, offerte, eventi, notizie, contenuti e categorie.": "Search across shops, products, deals, events, news, content and categories.",
  "Sono il tuo assistente allo shopping su Radici Calabria. Posso aiutarti a trovare negozi, prodotti e servizi nella tua città.": "I'm your shopping assistant on Radici Calabria. I can help you find shops, products and services in your city.",
  "La guida di Radici Calabria invita a scoprire le tradizioni gastronomiche di Castrovillari e del Pollino, compresa la Cipolla Bianca. La vetrina Eccellenze Calabresi mostra i prodotti effettivamente pubblicati dai negozi.": "The Radici Calabria guide invites you to discover the food traditions of Castrovillari and the Pollino, including the White Onion. The Calabrian Excellence showcase displays the products actually published by shops.",

