  "milioni di euro, mentre l’attuazione del nuovo Complemento di Sviluppo Rurale (CSR 2023–2027) ha posto la Calabria ai vertici nazionali per velocità ed efficienza di spesa.":
    "million euros, while the implementation of the new Rural Development Complement (CSR 2023–2027) has placed Calabria among the national leaders for spending speed and efficiency.",
  "Gaglioppo, Magliocco e Greco: i vitigni che raccontano il territorio.":
    "Gaglioppo, Magliocco and Greco: the grape varieties that tell the story of the land.",
  "Uliveti secolari lungo le coste e nelle vallate interne della regione.":
    "Centuries-old olive groves along the coasts and in the inland valleys of the region.",
  "Clementine calabresi appena raccolte su un tavolo di legno":
    "Freshly picked Calabrian clementines on a wooden table",
  "La società [Inserisci Nome Azienda/Ditta] (di seguito, il “Gestore”) mette a disposizione degli utenti una piattaforma tecnologica web e i relativi servizi digitali e di comunicazione (di seguito, il “Sito” o la “Piattaforma”), finalizzati a consentire l'incontro, l'interazione e la conclusione di rapporti commerciali tra venditori indipendenti (di seguito, i “Venditori”) e potenziali acquirenti (di seguito, gli “Acquirenti”).":
    "The company [Company name] (hereinafter the “Controller”) provides users with a web technology platform and the related digital and communication services (hereinafter the “Site” or the “Platform”), designed to allow independent sellers (hereinafter the “Sellers”) and potential buyers (hereinafter the “Buyers”) to meet, interact and conclude commercial relationships.",

