  "Il trattamento dei dati personali avviene secondo l'Informativa Privacy di Radici Calabria e la normativa applicabile, incluso il Regolamento (UE) 2016/679 (GDPR). Ciascun utente professionale opera quale autonomo titolare del trattamento per i dati trattati nell'ambito delle proprie attività, nei limiti e secondo le rispettive responsabilità previste dalla normativa applicabile.":
    "Personal data are processed in accordance with the Radici Calabria Privacy Notice and applicable law, including Regulation (EU) 2016/679 (GDPR). Each professional user acts as an independent data controller for the data processed within its own activities, within the limits and according to the respective responsibilities laid down by applicable law.",
  "La Piattaforma integra e utilizza servizi, contenuti e strumenti informativi forniti da soggetti terzi, inclusi i componenti e i widget informativi resi disponibili all'interno della Piattaforma. I dati, le informazioni, gli aggiornamenti e i risultati visualizzati attraverso tali componenti sono forniti e gestiti dai rispettivi soggetti o servizi di origine. La responsabilità dell'esattezza, completezza, aggiornamento, disponibilità e continuità di tali dati e informazioni è a carico del relativo soggetto o servizio di origine, secondo le proprie condizioni e responsabilità. Radici Calabria non modifica né garantisce autonomamente tali dati e non assume responsabilità per eventuali inesattezze, ritardi, omissioni, indisponibilità o interruzioni imputabili al servizio o al soggetto che li fornisce, fatti salvi gli obblighi inderogabili previsti dalla legge.":
    "The Platform integrates and uses services, content and information tools provided by third parties, including information components and widgets made available within the Platform. The data, information, updates and results displayed through those components are provided and managed by the respective source parties or services. Responsibility for the accuracy, completeness, updating, availability and continuity of such data and information lies with the relevant source party or service, under its own terms and responsibilities. Radici Calabria does not modify or independently guarantee such data and accepts no liability for any inaccuracies, delays, omissions, unavailability or interruptions attributable to the service or party providing them, without prejudice to mandatory obligations under the law.",
